def painters_partition(boards: list[int], k: int) -> int:
    def painters(cap: int) -> int:
        cnt, cur = 1, 0
        for b in boards:
            if cur + b > cap:
                cnt += 1
                cur = 0
            cur += b
        return cnt

    lo, hi = max(boards), sum(boards)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if painters(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
